use clap::Command;
use std::fmt::Write as _;

/// Render every command's Clap-generated long help as a Markdown reference.
pub(crate) fn render(mut command: Command) -> String {
    let mut markdown = String::from(
        "<!-- Generated by `lynx reference`; edit command definitions instead. -->\n\n",
    );
    markdown.push_str("# Lynx CLI reference\n\n");
    render_command(&mut command, "lynx", &mut markdown);
    markdown
}

fn render_command(command: &mut Command, path: &str, markdown: &mut String) {
    let _ = writeln!(markdown, "## `{path}`\n\n```text");
    let mut help = Vec::new();
    command
        .write_long_help(&mut help)
        .expect("writing Clap help to memory succeeds");
    markdown.push_str(std::str::from_utf8(&help).expect("Clap help is UTF-8"));
    if !markdown.ends_with('\n') {
        markdown.push('\n');
    }
    markdown.push_str("```\n\n");

    for subcommand in command.get_subcommands_mut() {
        if subcommand.is_hide_set() {
            continue;
        }
        let name = subcommand.get_name().to_owned();
        let child_path = format!("{path} {name}");
        render_command(subcommand, &child_path, markdown);
    }
}
